const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.processedMessageIds)) {
  staticData.processedMessageIds = [];
}

function extractEmail(value) {
  if (!value) return '';
  if (typeof value === 'string') {
    const m = value.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    return (m ? m[0] : value).trim();
  }
  if (Array.isArray(value)) return extractEmail(value[0]);
  if (typeof value === 'object') {
    return extractEmail(value.address || value.email || value.value || value.text || value.name || '');
  }
  return String(value);
}

function extractBody(item) {
  let text = item.text || item.textPlain || item.snippet || '';
  if (typeof text === 'object') text = text.plain || text.html || '';
  text = String(text || '').trim();
  if (text) return text;

  let html = item.html || item.textAsHtml || '';
  if (typeof html === 'object') html = html.data || '';
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const item = $input.first().json;
const messageId = item.id || item.messageId;
if (!messageId) throw new Error('Missing Gmail message id');

if (staticData.processedMessageIds.includes(messageId)) return [];
staticData.processedMessageIds.push(messageId);
if (staticData.processedMessageIds.length > 500) {
  staticData.processedMessageIds = staticData.processedMessageIds.slice(-500);
}

const subject = item.subject || item.Subject || '';
const replyTo = extractEmail(item.replyTo || item.from || item.From || '');
const fromDisplay = typeof (item.from || item.From) === 'string'
  ? (item.from || item.From)
  : replyTo;
const emailBody = extractBody(item);

if (!emailBody) {
  throw new Error('Email body is empty — OpenAI cannot qualify this lead');
}

return [{
  json: {
    messageId,
    threadId: item.threadId,
    subject,
    from: fromDisplay,
    replyTo,
    emailBody,
    receivedAt: item.date || item.internalDate || new Date().toISOString(),
    labelIds: item.labelIds || []
  }
}];

