const email = $('Idempotency + Prepare Email').first().json;
const aiItem = $input.first().json;

function tryParseJson(value) {
  if (value == null) return null;
  if (typeof value === 'object' && !Array.isArray(value)) {
    if (value.projectType != null || value.fitScore != null) return value;
    if (typeof value.text === 'string') return tryParseJson(value.text);
    if (Array.isArray(value.content)) {
      const joined = value.content.map((p) => (typeof p === 'string' ? p : p?.text || '')).join('\n');
      return tryParseJson(joined);
    }
    if (typeof value.content === 'string') return tryParseJson(value.content);
    return value;
  }
  if (typeof value !== 'string') return null;
  let raw = value.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(raw); } catch (e) {}
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch (e) {}
  }
  return null;
}

let parsed =
  tryParseJson(aiItem.message?.content) ||
  tryParseJson(aiItem.message) ||
  tryParseJson(aiItem.choices?.[0]?.message?.content) ||
  tryParseJson(aiItem.content) ||
  tryParseJson(aiItem.output) ||
  tryParseJson(aiItem.text) ||
  tryParseJson(aiItem) ||
  {};

if (parsed.projectType == null && parsed.fitScore == null) {
  parsed = tryParseJson(JSON.stringify(aiItem)) || {};
}

const fitScore = Math.max(1, Math.min(10, Number(parsed.fitScore) || 1));
let leadQuality = parsed.leadQuality;
if (!leadQuality) {
  leadQuality = fitScore >= 7 ? 'High' : fitScore >= 4 ? 'Medium' : 'Low';
}

return [{
  json: {
    messageId: email.messageId,
    threadId: email.threadId,
    from: email.from,
    replyTo: email.replyTo || email.from,
    subject: email.subject,
    emailBody: email.emailBody,
    timestamp: new Date().toISOString(),
    projectType: parsed.projectType || 'Unknown',
    budgetRange: parsed.budgetRange || 'Unknown',
    timeline: parsed.timeline || 'Unknown',
    keyRequirements: parsed.keyRequirements || 'Unable to extract requirements',
    fitScore,
    leadQuality,
    aiFailed: false,
    errorMessage: '',
    aiRawPreview: JSON.stringify(aiItem).slice(0, 500)
  }
}];

const email = $('Idempotency + Prepare Email').first().json;
const err = $input.first().json;

return [{
  json: {
    messageId: email.messageId,
    threadId: email.threadId,
    from: email.from,
    replyTo: email.replyTo || email.from,
    subject: email.subject,
    emailBody: email.emailBody,
    timestamp: new Date().toISOString(),
    projectType: 'AI Error',
    budgetRange: 'Unknown',
    timeline: 'Unknown',
    keyRequirements: `OpenAI failed: ${err.message || err.error?.message || JSON.stringify(err).slice(0, 300)}`,
    fitScore: 0,
    leadQuality: 'Error',
    aiFailed: true,
    errorMessage: err.message || err.error?.message || 'OpenAI request failed'
  }
}];

